MAP
    NAME "SS_MAP_LECT_PREDIOS_TRATADA"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_predios_tratada.log"
    DEBUG 0
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_LECT_PREDIOS_TRATADA"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        STATUS DEFAULT
        INCLUDE 'includes/conexion_gestion_infra.map'
        DATA "gm_predio from (select id_predio, gm_predio, cl_giro from op.mv_gm_predio_cuenta where cl_giro in (239,240,241,257,254) and cl_estatus_servicio = 'A' ) as pc using unique id_predio using srid=32614" 
        TYPE polygon
        CLASSITEM "cl_giro"
        CLASS
            NAME "AGUA TRATADA USO INDUSTRIAL"
            EXPRESSION "239"
            STYLE
                COLOR 224 192 224
                OUTLINECOLOR 224 192 224
            END #STYLE
        END #CLASS
        CLASS
            NAME "AGUA TRATADA RIEGO AREAS VERDES"
            EXPRESSION "240"
            STYLE
                COLOR 190 96 190
                OUTLINECOLOR 190 96 190
            END #STYLE
        END #CLASS
        CLASS
            NAME "AGUA TRATADA PROCESOS CONSTRUCCION"
            EXPRESSION "241"
            STYLE
                COLOR 150 30 150
                OUTLINECOLOR 150 30 150
            END #STYLE
        END #CLASS
        CLASS
            NAME "AGUA TRATADA EN TOMA DOMICILIARIA"
            EXPRESSION "257"
            STYLE
                COLOR 120 20 120
                OUTLINECOLOR 120 20 120
            END #STYLE
        END #CLASS
        CLASS
            NAME "TENERIA AGUA TRATADA"
            EXPRESSION "254"
            STYLE
                COLOR 80 10 80
                OUTLINECOLOR 80 10 80
            END #STYLE
        END #CLASS
    END #LAYER
END #MAP